jQuery(document).ready(function($)
{
    $(".w3eden .form-control").attr("placeholder", "Search PDF....");
	
	//var pgurl = window.location.href;
	const queryString = window.location.search;
	const urlParams = new URLSearchParams(queryString);
	const service = urlParams.get('service');
	
	jQuery(".react-btn a.elementor-button-link").each(function(index, item) {		
		if(jQuery(item).find('.elementor-button-text').text() == service){
			jQuery(item).addClass("active");
		}
		else {
			jQuery(item).removeClass("active");
		}
      });
	  	
});

jQuery(document).on('click', '.react-btn a.elementor-button-link', function(event){
		event.preventDefault();
		var btnText = jQuery(this).find('.elementor-button-text').text();
		jQuery('.react-btn a.elementor-button-link').removeClass("active");
		jQuery(this).addClass("active");
		jQuery('[name="dynamictext-255"]').val(btnText);
	});


